body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f8f9fa;
}

.container {
    padding: 20px;
}

header {
    text-align: center;
    margin-bottom: 20px;
}

#visualization-container {
    display: flex;
    flex-direction: row;
    justify-content: space-around;
    align-items: flex-start;
}

#chart-area {
    width: 60%;
    position: relative;
    background-color: white;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    padding: 10px;
}

#table-area {
    width: 35%;
    max-height: 800px;
    overflow-y: auto;
    background-color: white;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    padding: 10px;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    text-align: left;
    padding: 12px;
    border-bottom: 1px solid #ddd;
}

th {
    background-color: #f1f3f5;
    position: sticky;
    top: 0;
}

tr:hover {
    background-color: #f1f3f5;
    cursor: pointer;
}

tr.highlighted {
    background-color: #e7f5ff !important;
    font-weight: bold;
}

.bubble {
    stroke: #fff;
    stroke-width: 1.5px;
    cursor: pointer;
    transition: stroke 0.2s, stroke-width 0.2s;
}

.bubble:hover {
    stroke: #000;
    stroke-width: 2px;
}

.bubble.highlighted {
    stroke: #000;
    stroke-width: 3px;
}

.label {
    font-size: 10px;
    text-anchor: middle;
    pointer-events: none;
    fill: #333;
    font-weight: bold;
}

.tooltip {
    position: absolute;
    text-align: center;
    padding: 8px;
    font: 12px sans-serif;
    background: rgba(0, 0, 0, 0.8);
    color: #fff;
    border-radius: 4px;
    pointer-events: none;
    z-index: 1000;
}

#legend {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    margin-top: 10px;
    font-size: 12px;
}

.legend-item {
    display: flex;
    align-items: center;
    margin-right: 15px;
    margin-bottom: 5px;
}

.legend-color {
    width: 12px;
    height: 12px;
    margin-right: 5px;
    border-radius: 50%;
}

