document.addEventListener('DOMContentLoaded', function() {
    const width = 800;
    const height = 600;

    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .attr("viewBox", `0 0 ${width} ${height}`);

    const tooltip = d3.select("#tooltip");

    d3.csv("data/stock-descriptions.csv").then(data => {
        // Data Processing
        data.forEach(d => {
            d.marketCap = d.marketCap ? +d.marketCap : null;
            d.isETF = !d.marketCap || !d.country || !d.website;
        });

        // Helper to format market cap
        const formatMarketCap = (val) => {
            if (!val) return "N/A";
            if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
            if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
            if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
            return val.toString();
        };

        // Populate Table
        const tableBody = d3.select("#stock-table tbody");
        const rows = tableBody.selectAll("tr")
            .data(data)
            .enter()
            .append("tr")
            .attr("id", d => `row-${d.ticker}`)
            .on("click", (event, d) => {
                highlightStock(d.ticker);
            });

        rows.append("td").text(d => d.ticker);
        rows.append("td").text(d => d['full name']);
        rows.append("td").text(d => d.sector);
        rows.append("td").text(d => formatMarketCap(d.marketCap));

        // Color Scale
        const sectors = Array.from(new Set(data.map(d => d.sector)));
        const color = d3.scaleOrdinal()
            .domain(sectors)
            .range(d3.schemeCategory10);

        // Legend
        const legend = d3.select("#legend");
        sectors.forEach(sector => {
            const item = legend.append("div").attr("class", "legend-item");
            item.append("div")
                .attr("class", "legend-color")
                .style("background-color", color(sector));
            item.append("span").text(sector);
        });

        // Bubble sizes
        const maxCap = d3.max(data, d => d.marketCap) || 1;
        const radiusScale = d3.scaleSqrt()
            .domain([0, maxCap])
            .range([10, 50]);

        data.forEach(d => {
            d.radius = d.isETF ? 15 : radiusScale(d.marketCap);
        });

        // Clusters center calculation
        const clusterCenters = {};
        sectors.forEach((sector, i) => {
            const angle = (i / sectors.length) * 2 * Math.PI;
            clusterCenters[sector] = {
                x: width / 2 + Math.cos(angle) * 150,
                y: height / 2 + Math.sin(angle) * 150
            };
        });

        // Force Simulation
        const simulation = d3.forceSimulation(data)
            .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.1))
            .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.1))
            .force("collide", d3.forceCollide(d => d.radius + 2))
            .force("center", d3.forceCenter(width / 2, height / 2))
            .on("tick", ticked);

        const node = svg.selectAll(".node")
            .data(data)
            .enter()
            .append("g")
            .attr("class", "node")
            .attr("id", d => `node-${d.ticker}`)
            .on("mouseover", (event, d) => {
                if (!d.isETF) {
                    tooltip.transition().duration(200).style("opacity", .9);
                    tooltip.html(`<strong>${d.ticker}</strong><br/>${d['full name']}<br/>${d.sector}`)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                }
            })
            .on("mouseout", () => {
                tooltip.transition().duration(500).style("opacity", 0);
            })
            .on("click", (event, d) => {
                highlightStock(d.ticker);
            });

        node.append("circle")
            .attr("class", "bubble")
            .attr("r", d => d.radius)
            .attr("fill", d => color(d.sector));

        node.append("text")
            .attr("class", "label")
            .attr("dy", ".3em")
            .text(d => d.ticker);

        function ticked() {
            node.attr("transform", d => `translate(${d.x},${d.y})`);
        }

        function highlightStock(ticker) {
            // Reset all
            d3.selectAll("tr").classed("highlighted", false);
            d3.selectAll(".bubble").classed("highlighted", false);

            // Highlight selected
            const selectedRow = d3.select(`#row-${ticker}`);
            selectedRow.classed("highlighted", true);

            // Scroll table to row
            const tableArea = document.getElementById('table-area');
            const rowElement = document.getElementById(`row-${ticker}`);
            if (rowElement) {
                tableArea.scrollTo({
                    top: rowElement.offsetTop - tableArea.offsetTop,
                    behavior: 'smooth'
                });
            }

            d3.select(`#node-${ticker} circle`).classed("highlighted", true);
        }
    });
});

